CREATE TYPE "NotificationType" AS ENUM ('PAYMENT_DUE','PAYMENT_MISSED','MEMBER_DEFAULTED','PAYOUT_HELD','PAYOUT_RELEASED','DEPOSIT_REQUIRED','DEPOSIT_REFUNDED','DEPOSIT_FORFEITED','GROUP_COMPLETED','GROUP_INVITE');
CREATE TABLE "Notification" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "type" "NotificationType" NOT NULL, "title" TEXT NOT NULL, "message" TEXT NOT NULL, "isRead" BOOLEAN NOT NULL DEFAULT false, "groupId" TEXT, "metadata" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Notification_pkey" PRIMARY KEY ("id"), CONSTRAINT "Notification_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE, CONSTRAINT "Notification_groupId_fkey" FOREIGN KEY ("groupId") REFERENCES "SusuGroup"("id") ON DELETE CASCADE);
CREATE INDEX "Notification_userId_isRead_idx" ON "Notification"("userId", "isRead"); CREATE INDEX "Notification_groupId_createdAt_idx" ON "Notification"("groupId", "createdAt");
